const b = $input.first().json.body || {};
const d = b.datos || {};

// Idempotencia: si el backend reintenta el mismo evento, no se avisa dos veces.
const sd = $getWorkflowStaticData('global');
sd.vistos = sd.vistos || [];
if (b.evento_id && sd.vistos.includes(b.evento_id)) return [];
if (b.evento_id) sd.vistos = [...sd.vistos, b.evento_id].slice(-300);

const c = d.cliente || {};
const e = d.envio || {};
const nombre = String(c.nombre || '').trim().split(' ')[0];
const hola = nombre ? `Hola ${nombre}` : 'Hola';
const money = (n) => n == null ? '' : new Intl.NumberFormat('es-AR', { style: 'currency', currency: d.moneda || 'ARS' }).format(n);
const link = d.link_pedido ? `\n\nVer mi pedido: ${d.link_pedido}` : '';
const items = (d.items || []).map(i => `• ${i.cantidad} x ${i.nombre}`).join('\n');

// WhatsApp Argentina: 549 + área + número (13 dígitos). Si no se puede
// normalizar con seguridad, no se envía (mejor no avisar que avisar a otro).
const tel = (() => {
  let t = String(c.telefono || '').replace(/\D/g, '').replace(/^00/, '');
  if (t.startsWith('54')) {
    if (!t.startsWith('549') && t.length === 12) t = '549' + t.slice(2);
    return t.length === 13 ? t : '';
  }
  t = t.replace(/^0/, '');
  return t.length === 10 ? '549' + t : '';
})();

const textos = {
  pagada: [`Recibimos tu pago · ${d.numero}`,
    `✅ *Recibimos tu pago*\n\n${hola}, confirmamos el pago de tu pedido *${d.numero}*.` +
    `${items ? '\n\n' + items : ''}${d.total != null ? '\n\n*Total:* ' + money(d.total) : ''}\n\nLo estamos preparando.${link}`],
  preparacion: [`Estamos preparando tu pedido · ${d.numero}`,
    `📦 *Estamos preparando tu pedido*\n\n${hola}, tu pedido *${d.numero}* ya está en preparación. Te avisamos cuando salga.${link}`],
  enviada: [`Tu pedido ${d.numero} está en camino`,
    `🚚 *Tu pedido está en camino*\n\n${hola}, despachamos tu pedido *${d.numero}*.` +
    `${e.transportista ? '\n*Transportista:* ' + e.transportista : ''}${e.codigo ? '\n*Seguimiento:* ' + e.codigo : ''}` +
    `${e.url ? '\n' + e.url : ''}${link}`],
  entregada: [`Pedido entregado · ${d.numero}`,
    `🎉 *Pedido entregado*\n\n${hola}, tu pedido *${d.numero}* figura como entregado. Si hay algún problema, respondé este mensaje.${link}`],
  cancelada: [`Pedido cancelado · ${d.numero}`,
    `⚠️ *Pedido cancelado*\n\n${hola}, tu pedido *${d.numero}* fue cancelado. Si tenés dudas, escribinos.${link}`],
  reembolsada: [`Reembolso de tu pedido ${d.numero}`,
    `💸 *Reembolso realizado*\n\n${hola}, reembolsamos tu pedido *${d.numero}* por Mercado Pago. El tiempo de acreditación depende de tu medio de pago.${link}`],
};

const t = textos[d.estado];
if (!t) return []; // estados sin aviso (p. ej. pendiente)
return [{ json: {
  estado: d.estado, numero: d.numero,
  to_phone: tel, to_email: String(c.email || '').trim(),
  subject: t[0], texto: t[1],
} }];
